[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>GlobalStone — Global Commercial Real Estate Services</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary: #003F2D;
      --primary-dark: #012A2D;
      --primary-light: #005240;
      --accent: #C9A84C;
      --accent-hover: #E2C06A;
      --navy: #0A1628;
      --text-primary: #0A1628;
      --text-secondary: #4A5568;
      --text-muted: #718096;
      --surface: #FFFFFF;
      --surface-alt: #F7F8FA;
      --border: #E2E8F0;
      --gray-100: #F7F8FA;
      --gray-200: #E2E8F0;
      --gray-300: #CBD5E0;
      --font-display: 'Playfair Display', Georgia, serif;
      --font-body: 'Plus Jakarta Sans', system-ui, sans-serif;
    }

    html { scroll-behavior: smooth; }
    body { font-family: var(--font-body); color: var(--text-primary); background: #fff; line-height: 1.6; -webkit-font-smoothing: antialiased; }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    /* ─── HEADER ─── */
    .site-header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: rgba(10, 22, 40, 0.97);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(255,255,255,0.08);
    }
    .header-inner {
      max-width: 1440px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 40px; height: 70px;
    }
    .logo {
      font-family: var(--font-display); font-size: 22px; font-weight: 700;
      color: #fff; letter-spacing: -0.3px;
      display: flex; align-items: center; gap: 10px;
    }
    .logo-mark {
      width: 32px; height: 32px; background: var(--accent);
      clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
      flex-shrink: 0;
    }

    .main-nav { display: flex; align-items: center; gap: 4px; }
    .nav-item { position: relative; }
    .nav-link {
      display: block; padding: 8px 14px;
      font-size: 13.5px; font-weight: 500; color: rgba(255,255,255,0.85);
      letter-spacing: 0.2px; cursor: pointer; transition: color 0.2s;
      border-radius: 4px; white-space: nowrap;
    }
    .nav-link:hover, .nav-link.active { color: #fff; }
    .nav-link.has-dropdown::after {
      content: ''; display: inline-block; width: 6px; height: 6px;
      border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor;
      transform: rotate(45deg) translateY(-2px); margin-left: 6px; vertical-align: middle;
      transition: transform 0.2s;
    }
    .nav-item:hover .nav-link.has-dropdown::after,
    .nav-item.open .nav-link.has-dropdown::after { transform: rotate(-135deg) translateY(-2px); }

    /* MEGA MENU */
    .mega-menu {
      position: absolute; top: calc(100% + 1px); left: 50%; transform: translateX(-50%);
      width: 640px; background: #fff;
      border: 1px solid var(--border); border-radius: 8px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.15);
      padding: 28px 32px;
      opacity: 0; visibility: hidden; pointer-events: none;
      transform: translateX(-50%) translateY(-8px);
      transition: opacity 0.22s ease, transform 0.22s ease, visibility 0.22s;
    }
    .nav-item:hover .mega-menu,
    .nav-item.open .mega-menu {
      opacity: 1; visibility: visible; pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega-menu-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; }
    .mega-col-title {
      font-size: 10px; font-weight: 700; letter-spacing: 1.5px;
      text-transform: uppercase; color: var(--text-muted);
      margin-bottom: 14px; padding-bottom: 8px;
      border-bottom: 1px solid var(--border);
    }
    .mega-link {
      display: block; padding: 7px 0;
      font-size: 13.5px; font-weight: 500; color: var(--text-primary);
      transition: color 0.15s; border-bottom: 1px solid transparent;
    }
    .mega-link:hover { color: var(--primary); padding-left: 6px; }
    .mega-link-badge {
      display: inline-block; font-size: 10px; padding: 1px 6px;
      background: var(--gray-100); color: var(--text-muted);
      border-radius: 20px; margin-left: 8px; vertical-align: middle;
    }

    .header-actions { display: flex; align-items: center; gap: 12px; }
    .btn-contact {
      padding: 8px 20px; font-size: 13px; font-weight: 600;
      background: var(--accent); color: var(--navy);
      border-radius: 4px; transition: background 0.2s, transform 0.15s;
      letter-spacing: 0.2px;
    }
    .btn-contact:hover { background: var(--accent-hover); transform: translateY(-1px); }

    /* MOBILE MENU TOGGLE */
    .mobile-toggle {
      display: none; flex-direction: column; gap: 5px;
      background: none; border: none; cursor: pointer; padding: 6px;
    }
    .mobile-toggle span {
      display: block; width: 24px; height: 2px; background: #fff;
      transition: all 0.3s;
    }

    /* MOBILE DRAWER */
    .mobile-drawer {
      display: none; position: fixed; top: 70px; left: 0; right: 0; bottom: 0;
      background: var(--navy); overflow-y: auto; z-index: 999;
      padding: 20px 24px 40px;
      transform: translateX(100%); transition: transform 0.3s ease;
    }
    .mobile-drawer.open { transform: translateX(0); }
    .mobile-nav-link {
      display: flex; align-items: center; justify-content: space-between;
      padding: 14px 0; font-size: 16px; font-weight: 500; color: rgba(255,255,255,0.9);
      border-bottom: 1px solid rgba(255,255,255,0.1); cursor: pointer;
    }
    .mobile-nav-link .chevron {
      width: 8px; height: 8px;
      border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
      transform: rotate(45deg); transition: transform 0.2s;
    }
    .mobile-accordion { overflow: hidden; max-height: 0; transition: max-height 0.3s ease; }
    .mobile-accordion.open { max-height: 400px; }
    .mobile-accordion-item {
      display: block; padding: 10px 16px; font-size: 14px;
      color: rgba(255,255,255,0.7); border-bottom: 1px solid rgba(255,255,255,0.06);
    }
    .mobile-accordion-item:hover { color: #fff; }
    .mobile-accordion-title {
      font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase;
      color: var(--accent); padding: 12px 16px 4px;
    }

    /* ─── HERO ─── */
    .hero {
      position: relative; min-height: 680px;
      display: flex; align-items: center;
      background: var(--navy);
      overflow: hidden;
    }
    .hero-bg {
      position: absolute; inset: 0;
      background: linear-gradient(135deg, #0A1628 0%, #003F2D 50%, #012A2D 100%);
    }
    .hero-bg-pattern {
      position: absolute; inset: 0; opacity: 0.05;
      background-image: repeating-linear-gradient(
        -45deg,
        transparent, transparent 40px,
        rgba(255,255,255,0.3) 40px, rgba(255,255,255,0.3) 41px
      );
    }
    .hero-image-overlay {
      position: absolute; right: 0; top: 0; bottom: 0; width: 55%;
      background: linear-gradient(to right, var(--navy) 0%, transparent 30%),
        url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1200&q=80') center/cover no-repeat;
      opacity: 0.5;
    }
    .hero-inner {
      position: relative; z-index: 2;
      max-width: 1440px; margin: 0 auto; padding: 120px 40px 80px;
      width: 100%;
    }
    .hero-eyebrow {
      display: inline-flex; align-items: center; gap: 8px;
      font-size: 11px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase;
      color: var(--accent); margin-bottom: 24px;
    }
    .hero-eyebrow::before {
      content: ''; width: 32px; height: 2px; background: var(--accent);
    }
    .hero-title {
      font-family: var(--font-display); font-size: clamp(36px, 5vw, 62px);
      font-weight: 700; color: #fff; line-height: 1.1;
      max-width: 640px; margin-bottom: 24px; letter-spacing: -1px;
    }
    .hero-subtitle {
      font-size: 17px; font-weight: 400; color: rgba(255,255,255,0.7);
      max-width: 520px; line-height: 1.7; margin-bottom: 40px;
    }
    .hero-cta {
      display: inline-flex; align-items: center; gap: 10px;
      padding: 14px 32px; font-size: 14px; font-weight: 600;
      background: var(--accent); color: var(--navy);
      border-radius: 4px; transition: all 0.2s; letter-spacing: 0.3px;
    }
    .hero-cta:hover { background: var(--accent-hover); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(201,168,76,0.4); }
    .hero-cta svg { width: 16px; height: 16px; }

    .hero-stats {
      display: flex; gap: 48px; margin-top: 64px;
      padding-top: 40px; border-top: 1px solid rgba(255,255,255,0.12);
    }
    .stat-item {}
    .stat-num { font-family: var(--font-display); font-size: 36px; font-weight: 700; color: #fff; }
    .stat-label { font-size: 12px; color: rgba(255,255,255,0.55); letter-spacing: 0.5px; margin-top: 2px; }

    /* ─── ANNOUNCEMENT BANNER ─── */
    .announcement-banner {
      background: var(--primary); padding: 16px 40px;
      display: flex; align-items: center; justify-content: center; gap: 20px;
    }
    .announcement-text {
      font-size: 14px; font-weight: 500; color: rgba(255,255,255,0.9);
    }
    .announcement-cta {
      font-size: 13px; font-weight: 600; color: var(--accent);
      display: flex; align-items: center; gap: 6px; white-space: nowrap;
    }
    .announcement-cta:hover { color: var(--accent-hover); }
    .announcement-cta::after { content: '→'; }

    /* ─── SECTION WRAPPER ─── */
    .section { padding: 80px 40px; max-width: 1440px; margin: 0 auto; }
    .section-full { padding: 80px 0; }
    .section-label {
      font-size: 10.5px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase;
      color: var(--primary); margin-bottom: 12px;
      display: flex; align-items: center; gap: 10px;
    }
    .section-label::after { content: ''; flex: 1; max-width: 40px; height: 2px; background: var(--primary); }
    .section-title {
      font-family: var(--font-display); font-size: clamp(28px, 3.5vw, 44px);
      font-weight: 700; color: var(--text-primary); line-height: 1.15;
      letter-spacing: -0.5px;
    }
    .section-subtitle { font-size: 16px; color: var(--text-secondary); max-width: 560px; line-height: 1.7; margin-top: 12px; }

    /* ─── FEATURED INSIGHTS ─── */
    .featured-insights-section { background: var(--gray-100); padding: 72px 0; }
    .featured-insights-inner { max-width: 1440px; margin: 0 auto; padding: 0 40px; }
    .insights-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 40px; }
    .insight-card {
      background: #fff; border-radius: 8px; overflow: hidden;
      border: 1px solid var(--border);
      transition: transform 0.25s, box-shadow 0.25s;
      cursor: pointer;
    }
    .insight-card:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(0,0,0,0.1); }
    .insight-img {
      height: 200px; width: 100%;
      object-fit: cover;
    }
    .insight-img-placeholder {
      height: 200px; width: 100%;
      display: flex; align-items: center; justify-content: center;
      font-size: 13px; font-weight: 500; color: rgba(255,255,255,0.7);
    }
    .insight-body { padding: 24px; }
    .insight-tag {
      font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase;
      color: var(--primary); margin-bottom: 10px;
    }
    .insight-title { font-size: 16px; font-weight: 600; line-height: 1.4; color: var(--text-primary); margin-bottom: 8px; }
    .insight-title:hover { color: var(--primary); }
    .insight-meta { font-size: 12px; color: var(--text-muted); }
    .insight-link {
      display: inline-flex; align-items: center; gap: 6px;
      font-size: 13px; font-weight: 600; color: var(--primary);
      margin-top: 16px; transition: gap 0.2s;
    }
    .insight-link:hover { gap: 10px; }
    .insight-link::after { content: '→'; }

    /* ─── ABOUT STATEMENT ─── */
    .about-section { padding: 96px 40px; }
    .about-inner { max-width: 1440px; margin: 0 auto; display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center; }
    .about-text { }
    .about-title {
      font-family: var(--font-display); font-size: clamp(32px, 3vw, 46px);
      font-weight: 700; color: var(--text-primary); line-height: 1.2; margin-bottom: 24px;
    }
    .about-body { font-size: 16px; color: var(--text-secondary); line-height: 1.8; margin-bottom: 32px; }
    .btn-primary {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 13px 28px; font-size: 14px; font-weight: 600;
      background: var(--primary); color: #fff;
      border-radius: 4px; transition: all 0.2s;
    }
    .btn-primary:hover { background: var(--primary-light); transform: translateY(-1px); }
    .btn-primary::after { content: '→'; }
    .about-visual {
      position: relative; height: 420px; border-radius: 12px; overflow: hidden;
    }
    .about-visual-img {
      width: 100%; height: 100%;
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
      display: flex; align-items: center; justify-content: center;
    }
    .about-visual-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.85; }
    .about-accent-card {
      position: absolute; bottom: 32px; left: -32px;
      background: var(--accent); color: var(--navy);
      padding: 20px 28px; border-radius: 8px;
      box-shadow: 0 12px 32px rgba(201,168,76,0.4);
    }
    .about-accent-num { font-family: var(--font-display); font-size: 40px; font-weight: 700; line-height: 1; }
    .about-accent-text { font-size: 12px; font-weight: 600; margin-top: 4px; letter-spacing: 0.5px; }

    /* ─── WHAT WE DO TABS ─── */
    .what-we-do-section { background: var(--navy); padding: 96px 0; }
    .what-we-do-inner { max-width: 1440px; margin: 0 auto; padding: 0 40px; }
    .wwd-header { margin-bottom: 56px; }
    .wwd-header .section-label { color: var(--accent); }
    .wwd-header .section-label::after { background: var(--accent); }
    .wwd-header .section-title { color: #fff; }
    .wwd-layout { display: grid; grid-template-columns: 280px 1fr; gap: 0; }
    .wwd-tabs { border-right: 1px solid rgba(255,255,255,0.12); }
    .wwd-tab {
      display: block; padding: 20px 28px; font-size: 15px; font-weight: 500;
      color: rgba(255,255,255,0.55); cursor: pointer;
      border-left: 3px solid transparent;
      transition: all 0.2s;
    }
    .wwd-tab:hover { color: rgba(255,255,255,0.85); background: rgba(255,255,255,0.04); }
    .wwd-tab.active { color: #fff; border-left-color: var(--accent); background: rgba(255,255,255,0.06); }
    .wwd-panels { padding: 0 56px; }
    .wwd-panel { display: none; }
    .wwd-panel.active { display: block; animation: fadeIn 0.3s ease; }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
    .wwd-panel-eyebrow { font-size: 10px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); margin-bottom: 20px; }
    .wwd-panel-title { font-family: var(--font-display); font-size: 36px; font-weight: 700; color: #fff; line-height: 1.2; margin-bottom: 20px; }
    .wwd-panel-body { font-size: 16px; color: rgba(255,255,255,0.65); line-height: 1.8; margin-bottom: 32px; max-width: 480px; }
    .btn-outline-gold {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 12px 26px; font-size: 13.5px; font-weight: 600;
      border: 1.5px solid var(--accent); color: var(--accent);
      border-radius: 4px; transition: all 0.2s;
    }
    .btn-outline-gold:hover { background: var(--accent); color: var(--navy); }
    .btn-outline-gold::after { content: '→'; }

    /* ─── NEWSLETTER ─── */
    .newsletter-section {
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
      padding: 72px 40px;
    }
    .newsletter-inner {
      max-width: 1440px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between; gap: 48px;
    }
    .newsletter-text { }
    .newsletter-title { font-family: var(--font-display); font-size: 34px; font-weight: 700; color: #fff; margin-bottom: 12px; }
    .newsletter-sub { font-size: 16px; color: rgba(255,255,255,0.7); max-width: 440px; }
    .newsletter-form { display: flex; gap: 0; flex-shrink: 0; }
    .newsletter-input {
      width: 280px; padding: 14px 20px; font-size: 14px;
      background: rgba(255,255,255,0.12); border: 1px solid rgba(255,255,255,0.25);
      border-right: none; color: #fff; outline: none;
      border-radius: 4px 0 0 4px; font-family: var(--font-body);
    }
    .newsletter-input::placeholder { color: rgba(255,255,255,0.5); }
    .newsletter-input:focus { border-color: var(--accent); background: rgba(255,255,255,0.15); }
    .newsletter-btn {
      padding: 14px 24px; font-size: 13.5px; font-weight: 700;
      background: var(--accent); color: var(--navy);
      border: none; cursor: pointer; border-radius: 0 4px 4px 0;
      font-family: var(--font-body); letter-spacing: 0.5px;
      transition: background 0.2s;
    }
    .newsletter-btn:hover { background: var(--accent-hover); }

    /* ─── LATEST INSIGHTS ─── */
    .latest-insights-section { padding: 80px 0; }
    .latest-insights-inner { max-width: 1440px; margin: 0 auto; padding: 0 40px; }
    .insights-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 40px; }
    .view-all {
      font-size: 13.5px; font-weight: 600; color: var(--primary);
      display: flex; align-items: center; gap: 6px; transition: gap 0.2s;
    }
    .view-all:hover { gap: 10px; }
    .view-all::after { content: '→'; }
    .latest-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
    .latest-card {
      display: flex; flex-direction: column;
      border-bottom: 3px solid transparent;
      transition: border-color 0.2s;
      padding-bottom: 24px;
    }
    .latest-card:hover { border-bottom-color: var(--primary); }
    .latest-img {
      height: 220px; border-radius: 8px; overflow: hidden; margin-bottom: 20px;
      background: linear-gradient(135deg, #e8ecf0 0%, #d0d6de 100%);
    }
    .latest-img img { width: 100%; height: 100%; object-fit: cover; }
    .latest-category {
      font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase;
      color: var(--primary); margin-bottom: 8px;
      display: flex; align-items: center; gap: 8px;
    }
    .latest-category-sep { width: 16px; height: 1px; background: var(--primary); }
    .latest-title { font-size: 17px; font-weight: 600; line-height: 1.4; color: var(--text-primary); margin-bottom: 12px; }
    .latest-date { font-size: 12px; color: var(--text-muted); }

    /* ─── COMMITMENT ─── */
    .commitment-section { background: var(--gray-100); padding: 80px 0; }
    .commitment-inner { max-width: 1440px; margin: 0 auto; padding: 0 40px; }
    .commitment-header { margin-bottom: 48px; }
    .commitment-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
    .commitment-card {
      background: #fff; padding: 36px 28px; border-radius: 8px;
      border: 1px solid var(--border);
      transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;
    }
    .commitment-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(0,0,0,0.08); border-color: var(--primary); }
    .commitment-icon {
      width: 48px; height: 48px; background: var(--gray-100);
      border-radius: 8px; display: flex; align-items: center; justify-content: center;
      margin-bottom: 20px; color: var(--primary);
    }
    .commitment-card-title { font-size: 17px; font-weight: 700; color: var(--text-primary); margin-bottom: 12px; }
    .commitment-card-body { font-size: 14px; color: var(--text-secondary); line-height: 1.7; margin-bottom: 20px; }
    .read-more {
      font-size: 13px; font-weight: 600; color: var(--primary);
      display: flex; align-items: center; gap: 6px; transition: gap 0.2s;
    }
    .read-more:hover { gap: 10px; }
    .read-more::after { content: '→'; }

    /* ─── FOOTER ─── */
    .site-footer { background: var(--navy); padding: 64px 40px 32px; }
    .footer-inner { max-width: 1440px; margin: 0 auto; }
    .footer-top { display: grid; grid-template-columns: 260px 1fr; gap: 80px; padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,0.1); }
    .footer-brand { }
    .footer-logo { font-family: var(--font-display); font-size: 20px; font-weight: 700; color: #fff; display: flex; align-items: center; gap: 10px; margin-bottom: 16px; }
    .footer-tagline { font-size: 13px; color: rgba(255,255,255,0.5); line-height: 1.7; }
    .footer-nav-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
    .footer-nav-col { }
    .footer-nav-title { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: rgba(255,255,255,0.4); margin-bottom: 16px; }
