  const sni = document.getElementById('services-nav-item');
  sni.addEventListener('mouseenter', () => sni.classList.add('open'));
  sni.addEventListener('mouseleave', () => sni.classList.remove('open'));
  sni.querySelector('.has-dropdown').addEventListener('click', e => { e.preventDefault(); sni.classList.toggle('open'); });
  document.addEventListener('click', e => { if (!sni.contains(e.target)) sni.classList.remove('open'); });
  const obs = new IntersectionObserver(entries => entries.forEach(e => { if (e.isIntersecting) { e.target.style.opacity='1'; e.target.style.transform='translateY(0)'; }}), {threshold:0.1});
  document.querySelectorAll('.cap-card-large, .metric-card, .process-step').forEach(el => { el.style.opacity='0'; el.style.transform='translateY(20px)'; el.style.transition='opacity 0.5s ease, transform 0.5s ease'; obs.observe(el); });
